    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=1||result!=RESULT_OK||data==null||data.getData()==null)return;stop();android.net.Uri uri=data.getData();int token=++loadGeneration;setReaderStatus(getString(R.string.ui_38));new Thread(()->{try{String name=getString(R.string.ui_39);try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}byte[] bytes;try(InputStream in=getContentResolver().openInputStream(uri)){bytes=readBytes(in);}String value=decode(bytes).replace("\uFEFF","").replace("\r\n","\n").replace('\r','\n').replace("\u0000","");if(value.trim().isEmpty())throw new IOException(getString(R.string.ui_40));ArrayList<Chapter> list=parse(value);final String finalName=name.replaceFirst("(?i)\\.txt$","");try(FileOutputStream out=openFileOutput("book.txt",MODE_PRIVATE)){out.write(value.getBytes(StandardCharsets.UTF_8));}runOnUiThread(()->{if(destroyed||token!=loadGeneration)return;text=value;book=finalName;chapters=list;position=0;chapter=0;title.setText(book);showPosition(true);setReaderStatus(getString(R.string.import_success,chapters.size(),text.length()));save();});}catch(Exception e){runOnUiThread(()->{if(!destroyed&&token==loadGeneration){setReaderStatus(getString(R.string.ui_44)+e.getMessage());toast(getString(R.string.ui_45));}});}}).start();}
    static byte[] readBytes(InputStream in)throws IOException{if(in==null)throw new IOException("Could not open file");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>30*1024*1024)throw new IOException("File exceeds 30 MB");out.write(b,0,n);}return out.toByteArray();}
    static String decode(byte[] b)throws CharacterCodingException{if(b.length>=2&&b[0]==(byte)0xff&&b[1]==(byte)0xfe)return new String(b,StandardCharsets.UTF_16LE);if(b.length>=2&&b[0]==(byte)0xfe&&b[1]==(byte)0xff)return new String(b,StandardCharsets.UTF_16BE);try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString();}catch(CharacterCodingException e){return Charset.forName("GB18030").newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString();}}
    static ArrayList<Chapter> parse(String value){ArrayList<Chapter> list=new ArrayList<>();Pattern p=Pattern.compile("(?im)^[\\t \\u3000]*(第[零〇一二两三四五六七八九十百千万0-9０-９]+[章节回卷部篇集][^\\n]{0,65}|chapter\\s+\\d+[^\\n]{0,65}|(?:序章|序言|楔子|前言|引子|尾声|后记|番外)[^\\n]{0,40})[\\t \\u3000]*$");Matcher m=p.matcher(value);while(m.find()){if(list.isEmpty()&&m.start()>0&&!value.substring(0,m.start()).trim().isEmpty())list.add(generatedChapter("序言",R.string.preface,0,m.start()));if(!list.isEmpty())list.get(list.size()-1).end=m.start();Chapter detected=new Chapter(m.group(1).trim(),m.start(),value.length());detected.bodyStart=m.end();list.add(detected);}if(list.isEmpty())list.add(generatedChapter("正文",R.string.body_text,0,value.length()));ArrayList<Chapter> result=new ArrayList<>();for(Chapter c:list){if(!hasChapterBody(value,c.bodyStart,c.end))continue;for(int start=c.start,part=1;start<c.end;part++){int end=Math.min(c.end,start+12000);if(end<c.end){int br=value.lastIndexOf('\n',end);if(br>start+6000)end=br+1;}if(hasChapterBody(value,Math.max(start,c.bodyStart),end))result.add(chapterSlice(c,part,start,end));start=end;}}return result;}
    static Chapter generatedChapter(String name,int resource,int start,int end){Chapter c=new Chapter(name,start,end);c.generatedTitle=resource;return c;}
    static Chapter chapterSlice(Chapter source,int part,int start,int end){Chapter c=new Chapter(source.name,start,end);c.generatedTitle=source.generatedTitle;c.part=part;return c;}
    String chapterName(Chapter c){String name=c.generatedTitle==0?c.name:getString(c.generatedTitle);return c.part==1?name:getString(R.string.continued,name,c.part);}
    static boolean hasChapterBody(String value,int start,int end){for(int i=start;i<end;){int cp=value.codePointAt(i);if(!Character.isWhitespace(cp)&&!Character.isSpaceChar(cp)&&Character.getType(cp)!=Character.FORMAT&&"-_—–─━═=＝＊*~～·•●○◆◇■□+|｜#＃﹏＿－".indexOf(cp)<0)return true;i+=Character.charCount(cp);}return false;}
    void restore(){if(!new File(getFilesDir(),bookFile).exists())return;setReaderStatus(getString(R.string.ui_52));new Thread(()->{try{String v;try(InputStream in=openFileInput(bookFile)){v=new String(readBytes(in),StandardCharsets.UTF_8);}ArrayList<Chapter> list=parse(v);runOnUiThread(()->{if(destroyed||loadGeneration!=0)return;text=v;chapters=list;book=prefs.getString("book",book);checkpointVersion=prefs.getLong("checkpointVersion",0);position=ReadingCheckpoint.restore(new File(getFilesDir(),bookFile+".position"),bookFile,v,prefs.getInt("position",0),checkpointVersion);title.setText(book);showPosition(true);if(position>0)highlight(position,Math.min(text.length(),position+1));setReaderStatus(getString(R.string.restored,chapters.size()));});}catch(Exception e){runOnUiThread(()->setReaderStatus(getString(R.string.ui_54)));}}).start();}
    void save(){save(false);}
    void save(boolean force){if(text.isEmpty())return;long now=SystemClock.elapsedRealtime();if(!force&&playing&&now-lastSaveAt<5000)return;lastSaveAt=now;checkpointVersion=Math.max(checkpointVersion+1,System.currentTimeMillis());SharedPreferences.Editor editor=prefs.edit().putString("book",book).putInt("position",position).putFloat("rate",rate).putLong("checkpointVersion",checkpointVersion).putInt("percent",(int)(100L*position/text.length()));if(force){ReadingCheckpoint.write(new File(getFilesDir(),bookFile+".position"),bookFile,text,position,checkpointVersion);editor.commit();}else editor.apply();}
    void showPosition(boolean force){
        if(chapters.isEmpty()){chapterTitle.setText(getString(R.string.ui_55));content.setText(getString(R.string.ui_56));return;}
        int index=0;for(int i=0;i<chapters.size();i++){if(position>=chapters.get(i).start)index=i;else break;}
        if(position<chapters.get(index).start)position=chapters.get(index).start;else if(position>=chapters.get(index).end){if(index+1<chapters.size())position=chapters.get(++index).start;else position=Math.max(chapters.get(index).start,chapters.get(index).end-1);}
        boolean changed=index!=chapter;chapter=index;PlaybackService.refreshActive(force||changed);if(!canDrawReader())return;
        if(index!=renderedChapter||force){
            if(force||!readingFollowBlocked()){
                // A programmatic chapter reset must not extend the manual-scroll timeout.
                resetReadingFollow();renderedChapter=index;Chapter c=chapters.get(chapter);chapterTitle.setText(chapterName(c));content.setText(text.substring(c.start,c.end));scroll.scrollTo(0,0);
            }else scheduleReadingFollow();
        }
        updateProgress();if(chapterPicker!=null)chapterPicker.refreshCurrent();
    }
    void updateProgress(){if(text.isEmpty()||chapters.isEmpty()||!canDrawReader())return;progressUpdates++;Chapter current=chapters.get(chapter);float fraction=ChapterProgress.fraction(position,current.start,current.end);if(!seeking)seek.setProgress(Math.round(1000*fraction));progress.setText(getString(R.string.chapter_progress,chapter+1,chapters.size(),100*fraction));}
    ReadingMediaState mediaState(){if(chapters.isEmpty()||chapter<0||chapter>=chapters.size())return null;Chapter current=chapters.get(chapter);if(mediaDurationChapter!=chapter||mediaDurationRate!=rate){mediaDuration=ReadingMediaState.estimateDuration(text,current.start,current.end,rate);mediaDurationChapter=chapter;mediaDurationRate=rate;}return new ReadingMediaState(book,chapterName(current),chapter,ChapterProgress.fraction(position,current.start,current.end),mediaDuration,playing,chapter>0,chapter+1<chapters.size());}
    void mediaJump(int delta){int target=chapter+delta;if(target<0||target>=chapters.size())return;resetReadingFollow();boolean resume=playing;stop(false);position=chapters.get(target).start;showPosition(true);save(true);if(resume)startReading();else PlaybackService.refreshActive(true);}
    void mediaSeek(float fraction){seekChapter(chapter,fraction);}
    void seekChapter(int index,float fraction){if(index<0||index>=chapters.size())return;resetReadingFollow();Chapter current=chapters.get(index);int wanted=ChapterProgress.position(fraction,current.start,current.end);int at=current.start;while(at<current.end){int end=nextSpeechEnd(text,at,current.end);if(end>wanted||end<=at)break;at=end;}boolean resume=playing;stop(!resume&&PlaybackService.active==null);position=Math.min(at,current.end-1);showPosition(true);save(true);if(resume)startReading();else PlaybackService.refreshActive(true);}
    void directory(){if(chapters.isEmpty()){toast(getString(R.string.ui_58));return;}if(chapterPicker!=null&&chapterPicker.isShowing())return;ArrayList<String> names=new ArrayList<>();for(Chapter item:chapters)names.add(chapterName(item));chapterPicker=new ChapterPicker(this,names,night,new ChapterPicker.Host(){public int current(){return chapter;}public void open(int index){resetReadingFollow();stop();position=chapters.get(index).start;showPosition(true);save();startReading();}});ChapterPicker opened=chapterPicker;opened.setOnDismissListener(d->{if(chapterPicker==opened)chapterPicker=null;});opened.show();}
    void jump(int i){if(chapters.isEmpty()){toast(getString(R.string.ui_58));return;}if(i<0||i>=chapters.size()){toast(getString(R.string.ui_59));return;}resetReadingFollow();boolean resume=playing;stop(!resume);position=chapters.get(i).start;showPosition(true);save();if(resume)startReading();}
    boolean usesSystem(){return !VoicePackages.isKey(systemVoiceKey);}
