        int action=event.getActionMasked();
        if(action==MotionEvent.ACTION_DOWN){swipeX=event.getX();swipeY=event.getY();swiping=false;int[] location=new int[2];scroll.getLocationInWindow(location);swipeEligible=swipeY>=location[1]&&swipeY<=location[1]+scroll.getHeight()+modeBar.getHeight();}
        if(action==MotionEvent.ACTION_MOVE&&swipeEligible){float dx=event.getX()-swipeX,dy=event.getY()-swipeY;if(!swiping&&Math.abs(dy)>dp(16)&&Math.abs(dy)>Math.abs(dx))swipeEligible=false;if(!swiping&&swipeEligible&&Math.abs(dx)>dp(16)&&Math.abs(dx)>Math.abs(dy)*1.5f&&((!readingMode&&dx<0)||(readingMode&&dx>0))){MotionEvent cancel=MotionEvent.obtain(event);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();beginModeSwipe(!readingMode);swiping=true;}if(swiping){renderModeSwipe(dx);return true;}}
