    String voiceLanguage(){return readingLanguage.isEmpty()?(originalVoiceLanguage.isEmpty()?VoiceLanguages.systemLanguage(this):originalVoiceLanguage):readingLanguage;}
    boolean ensureReadingVoice(){
        String language=voiceLanguage();VoicePackages packages=VoicePackages.get(this);String preferred=readingPrefs.getString(readingVoicePreference(language),"");
        if(packages.resolve(systemVoiceKey,language)!=null)return true;
        if(system!=null&&system.initialized){SystemSpeaker.Option current=system.find(systemVoiceKey);if(current!=null&&SystemSpeaker.offlineUsable(current.voice)&&VoiceLanguages.matches(language,current.voice.getLocale())){systemVoiceKey=current.key;return true;}}
        if(packages.resolve(preferred,language)!=null){systemVoiceKey=preferred;return true;}
        // An engine still initializing is not a missing voice. Keep the saved key until discovery finishes.
        if(system==null||!system.initialized)return false;
        SystemSpeaker.Option voice=system.offlineVoice(language,preferred);if(voice!=null){systemVoiceKey=voice.key;return true;}
        VoicePackages.Selection selected=packages.preferred(language,"");systemVoiceKey=selected==null?"":selected.pack.key(selected.speaker);return selected!=null;
    }
