        slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int p,boolean user){if(!user)return;if(speed){rate=.5f+p*.05f;value.setText(String.format(AppLanguage.locale(MainActivity.this),"%.2f×",rate));speedButton.setText(String.format(AppLanguage.locale(MainActivity.this),getString(R.string.ui_108),rate));readingPrefs.edit().putFloat("rate",rate).apply();save();}else{int size=14+p;int anchor=0;if(content.getLayout()!=null){int y=Math.max(0,scroll.getScrollY()-content.getTop());anchor=content.getLayout().getLineStart(content.getLayout().getLineForVertical(y));}final int at=anchor;content.setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP,size);content.requestLayout();sample.setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP,size);value.setText(size+" sp");readingPrefs.edit().putInt("font",size).apply();prefs.edit().putInt("font",size).apply();content.post(()->{if(content.getLayout()!=null){int line=content.getLayout().getLineForOffset(Math.min(at,content.length()));scroll.scrollTo(0,content.getTop()+content.getLayout().getLineTop(line));}});}}});
