    void scheduleModelRelease(){modelHandler.removeCallbacks(modelRelease);if(!destroyed&&!playing&&previewKey.isEmpty()&&offline!=null)modelHandler.postDelayed(modelRelease,MODEL_IDLE_MS);}
    void releaseIdleModel(){if(playing||!previewKey.isEmpty())return;modelHandler.removeCallbacks(modelRelease);if(offline!=null){offline.close();offline=null;}offlineReady=false;}
    void warmCurrentModel(){
        if(destroyed||!readerVisible||playing||pendingVoiceChange!=null||!previewKey.isEmpty())return;
        if(!ensureReadingVoice()||usesSystem()){releaseIdleModel();return;}
        VoicePackages.Selection selection=VoicePackages.get(this).resolve(systemVoiceKey,voiceLanguage());if(selection==null)return;
        if(offline instanceof PackageSpeaker){PackageSpeaker current=(PackageSpeaker)offline;if(current.key.equals(systemVoiceKey)&&current.language.equals(voiceLanguage())&&!current.closed){scheduleModelRelease();return;}}
        releaseIdleModel();PackageSpeaker next=new PackageSpeaker(this,selection,voiceLanguage());offline=next;offlineReady=false;
        next.init(error->{if(destroyed||offline!=next)return;if(error!=null){offlineReady=false;if(!playing&&previewKey.isEmpty()){next.close();offline=null;}}else offlineReady=true;scheduleModelRelease();});scheduleModelRelease();
    }
    void setPreviewKey(String key){if(key.isEmpty()&&previewGuard!=null)previewGuard.close();previewKey=key;if(voicePicker!=null)voicePicker.setPreviewKey(key);if(key.isEmpty())scheduleModelRelease();else modelHandler.removeCallbacks(modelRelease);}
    void prepareImported(String key,String language,Runnable ready,java.util.function.Consumer<Throwable> failed){
        final int token=generation;modelHandler.removeCallbacks(modelRelease);VoicePackages.Selection selected=VoicePackages.get(this).resolve(key,language);if(selected==null){failed.accept(new IOException("invalid"));return;}
        PackageSpeaker next=null;if(offline instanceof PackageSpeaker){PackageSpeaker current=(PackageSpeaker)offline;if(current.key.equals(key)&&current.language.equals(language)&&!current.closed)next=current;}
        if(next==null){if(offline!=null)offline.close();next=new PackageSpeaker(this,selected,language);offline=next;offlineReady=false;}
        final PackageSpeaker requested=next;if(requested.ready){ready.run();return;}
        requested.init(error->{if(destroyed||generation!=token||offline!=requested)return;if(error!=null){requested.close();offline=null;offlineReady=false;failed.accept(error);}else{offlineReady=true;ready.run();}});
    }
